const strip = (value) => String(value ?? '')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>')
  .replace(/&quot;/gi, '"')
  .replace(/&#0?39;/gi, "'")
  .replace(/\s+/g, ' ')
  .trim();
const state = $getWorkflowStaticData('global');
const seen = state.seenArticles ?? {};
const cutoff = Date.now() - 7 * 24 * 60 * 60 * 1000;
const unique = new Map();
for (const item of items) {
  const row = item.json ?? {};
  const url = String(row.link ?? row.guid ?? '').trim();
  const title = strip(row.title).slice(0, 300);
  if (!/^https:\/\//i.test(url) || !title || seen[url]) continue;
  const timestamp = Date.parse(row.isoDate ?? row.pubDate ?? row.published ?? '');
  if (Number.isFinite(timestamp) && timestamp < cutoff) continue;
  const host = (() => { try { return new URL(url).hostname; } catch { return ''; } })();
  const source = host.includes('microsoft.com') ? 'Microsoft Security'
    : host.includes('google.com') || host.includes('feedburner.com') ? 'Google Threat Intelligence'
    : host || 'Security research';
  const summary = strip(row.contentSnippet ?? row.content ?? row.description ?? row.summary).slice(0, 5000);
  if (!summary) continue;
  unique.set(url, { title, url, source, published: Number.isFinite(timestamp) ? new Date(timestamp).toISOString() : '', summary });
}
return [...unique.values()]
  .sort((a, b) => Date.parse(b.published || 0) - Date.parse(a.published || 0))
  .slice(0, 3)
  .map((json) => ({ json }));

const articles = $('Normalize and shortlist').all();
const parse = (value) => {
  if (value && typeof value === 'object') return value;
  const cleaned = String(value ?? '').replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
  try { return JSON.parse(cleaned); } catch {}
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start >= 0 && end > start) return JSON.parse(cleaned.slice(start, end + 1));
  throw new Error('Extractor did not return JSON');
};
const unique = (values, validator, normalize = (v) => v) => [...new Set(
  (Array.isArray(values) ? values : [])
    .filter((value) => typeof value === 'string')
    .map((value) => normalize(value.trim()))
    .filter(validator)
)].slice(0, 8);
const name = (value) => /^[A-Za-z0-9][A-Za-z0-9 ._+/@:-]{2,127}$/.test(value) && value.split(/\s+/).length <= 8;
const indicator = (value) => /^https?:\/\/[^\s]+$/i.test(value)
  || /^(?:[a-f0-9]{32}|[a-f0-9]{40}|[a-f0-9]{64})$/i.test(value)
  || /^(?:\d{1,3}\.){3}\d{1,3}$/.test(value)
  || /^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/i.test(value);
const state = $getWorkflowStaticData('global');
const seen = { ...(state.seenArticles ?? {}) };
const outputs = [];

for (let index = 0; index < items.length; index++) {
  const article = articles[index]?.json;
  if (!article?.url) continue;
  const current = items[index]?.json ?? {};
  const output = parse(current.message?.content ?? current.response ?? current);
  const entities = {
    actors: unique(output.actors, name),
    campaigns: unique(output.campaigns, name),
    malware: unique(output.malware, name),
    vulnerabilities: unique(output.vulnerabilities, (v) => /^CVE-[0-9]{4}-[0-9]{4,7}$/.test(v), (v) => v.toUpperCase()),
    techniques: unique(output.techniques, (v) => /^T[0-9]{4}(?:\.[0-9]{3})?$/.test(v), (v) => v.toUpperCase()),
    indicators: unique(output.indicators, indicator),
  };
  if (!Object.values(entities).some((values) => values.length)) {
    seen[article.url] = Date.now();
    continue;
  }
  outputs.push({ json: { article, entities }, pairedItem: { item: index } });
}

state.seenArticles = seen;
return outputs;

const extraction = $('Parse bounded entities').item.json;
const context = $json;
const seenHits = new Set();
const hits = [];
for (const hit of context.siem?.hits ?? []) {
  const excerpt = String(hit.excerpt ?? '').slice(0, 280);
  const labels = {
    host: hit.labels?.host,
    job: hit.labels?.job,
    unit: hit.labels?.unit,
    app: hit.labels?.app,
    facility: hit.labels?.facility,
  };
  const key = [hit.observed_at, labels.host, labels.job, labels.unit, excerpt].join('|');
  if (!excerpt || seenHits.has(key)) continue;
  seenHits.add(key);
  hits.push({
    observed_at: hit.observed_at,
    labels: Object.fromEntries(Object.entries(labels).filter(([, value]) => value)),
    matched_terms: (hit.matched_terms ?? []).slice(0, 8),
    excerpt,
  });
  if (hits.length >= 6) break;
}
const compactIntel = (item) => ({
  name: String(item.name ?? '').slice(0, 180),
  aliases: (Array.isArray(item.aliases) ? item.aliases : []).map(String).slice(0, 6),
  description: String(item.description ?? '').slice(0, 500),
  published: item.published,
  report_types: (Array.isArray(item.report_types) ? item.report_types : []).map(String).slice(0, 5),
});
const reviewContext = {
  terms: (context.terms ?? []).slice(0, 8),
  summary: context.summary ?? {},
  errors: context.errors ?? {},
  siem: { lookback: context.siem?.lookback, hits },
  opencti: {
    intrusion_sets: (context.opencti?.intrusion_sets ?? []).slice(0, 3).map(compactIntel),
    reports: (context.opencti?.reports ?? []).slice(0, 3).map(compactIntel),
  },
};
return { json: { ...extraction, context, reviewContext } };

const bases = $('Attach SOC context').all();
const parse = (value) => {
  if (value && typeof value === 'object') return value;
  const cleaned = String(value ?? '').replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
  try { return JSON.parse(cleaned); } catch {}
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start >= 0 && end > start) return JSON.parse(cleaned.slice(start, end + 1));
  throw new Error('Reviewer did not return JSON');
};
const state = $getWorkflowStaticData('global');
const now = Date.now();
const seen = { ...(state.seenArticles ?? {}) };
const outputs = [];

for (let index = 0; index < items.length; index++) {
  const base = bases[index]?.json;
  if (!base?.article?.url) continue;
  const current = items[index]?.json ?? {};
  const raw = current.message?.content ?? current.response ?? current;
  const review = parse(raw);
  const summary = base.context?.summary ?? {};
  const evidenceTerms = new Set((summary.matched_terms ?? []).map((value) => String(value).toLowerCase()));
  const reviewerTerms = (Array.isArray(review.matched_terms) ? review.matched_terms : [])
    .map((value) => String(value).trim())
    .filter((value) => evidenceTerms.has(value.toLowerCase()));
  const confidence = Math.max(0, Math.min(1, Number(review.confidence ?? 0)));
  const evidenceCount = Number(summary.siem_hit_count ?? 0)
    + Number(summary.report_count ?? 0)
    + Number(summary.intrusion_set_count ?? 0);
  seen[base.article.url] = now;
  const notify = summary.has_evidence === true
    && evidenceCount > 0
    && review.relevant === true
    && confidence >= 0.72
    && reviewerTerms.length > 0;
  if (!notify) continue;
  outputs.push({
    json: {
      ...base,
      review: {
        relevant: true,
        confidence,
        summary: String(review.summary ?? '').slice(0, 700),
        rationale: String(review.rationale ?? '').slice(0, 900),
        matched_terms: reviewerTerms.slice(0, 8),
        actions: (Array.isArray(review.actions) ? review.actions : []).map(String).slice(0, 5),
      },
      priority: Number(summary.siem_hit_count ?? 0) > 0
        && (Number(summary.report_count ?? 0) > 0 || Number(summary.intrusion_set_count ?? 0) > 0)
        && confidence >= 0.85 ? 5 : 4,
    },
    pairedItem: { item: index },
  });
}

state.seenArticles = Object.fromEntries(Object.entries(seen)
  .filter(([, timestamp]) => now - Number(timestamp) < 30 * 24 * 60 * 60 * 1000)
  .sort((left, right) => Number(right[1]) - Number(left[1]))
  .slice(0, 500));
return outputs;

const counts = $json.context.summary;
const reports = ($json.context.opencti?.reports ?? []).slice(0, 3).map((item) => item.name);
const hits = ($json.context.siem?.hits ?? []).slice(0, 2).map((item) => {
  const where = [item.labels?.host, item.labels?.job, item.labels?.unit].filter(Boolean).join('/');
  return '• ' + (where || 'SIEM') + ': ' + String(item.excerpt ?? '').slice(0, 420);
});
const actions = $json.review.actions.length ? '\nNext: ' + $json.review.actions.join('; ') : '';
const reportLine = reports.length ? '\nReports: ' + reports.join('; ') : '';
const hitLines = hits.length ? '\n' + hits.join('\n') : '';
const message = [
  $json.review.summary,
  'News: ' + $json.article.title + ' (' + $json.article.source + ')',
  'Matched: ' + $json.review.matched_terms.join(', '),
  'Evidence: ' + counts.siem_hit_count + ' SIEM hit(s) in ' + $json.context.siem.lookback + '; ' + counts.report_count + ' OpenCTI report(s); ' + counts.intrusion_set_count + ' intrusion set(s).',
  'Confidence: ' + Math.round($json.review.confidence * 100) + '% — ' + $json.review.rationale + reportLine + hitLines + actions,
].join('\n\n').slice(0, 3900);
return { json: {
  topic: 'thornixos-ops',
  title: ('Threat news ↔ SOC match · ' + $json.review.matched_terms[0]).slice(0, 150),
  message,
  priority: $json.priority,
  tags: ['shield', 'mag', 'robot_face'],
  click: $json.article.url,
} };

const fit = (value, limit = 1024) => {
  const safe = String(value ?? '').replaceAll('@', '@\u200b').trim();
  if (!safe) return 'Not provided.';
  if (safe.length <= limit) return safe;
  return safe.slice(0, limit - 2).trimEnd() + '…';
};
const article = $json.article ?? {};
const review = $json.review ?? {};
const counts = $json.context?.summary ?? {};
const matched = (Array.isArray(review.matched_terms) ? review.matched_terms : [])
  .map((value) => String(value).trim())
  .filter(Boolean)
  .slice(0, 8);
const actions = (Array.isArray(review.actions) ? review.actions : [])
  .map((value) => '• ' + String(value).trim())
  .filter((value) => value !== '•')
  .slice(0, 5);
const source = fit(article.source ?? 'Threat intelligence', 120);
const confidence = Math.round(Math.max(0, Math.min(1, Number(review.confidence ?? 0))) * 100);
const articleUrl = /^https?:\/\//i.test(String(article.url ?? '')) ? String(article.url) : '';
const evidence = [
  `SIEM hits: **${Number(counts.siem_hit_count ?? 0)}** (${fit($json.context?.siem?.lookback ?? 'bounded lookback', 80)})`,
  `OpenCTI reports: **${Number(counts.report_count ?? 0)}**`,
  `OpenCTI intrusion sets: **${Number(counts.intrusion_set_count ?? 0)}**`,
].join('\n');
const discordEmbed = {
  author: { name: 'GUILDEDTHORN // THREAT WATCH' },
  title: fit('Threat news ↔ SOC match · ' + (matched[0] ?? 'evidence'), 256),
  ...(articleUrl ? { url: articleUrl } : {}),
  description: fit(review.summary, 1200),
  color: Number($json.priority ?? 4) >= 5 ? 0xf38ba8 : 0xf9e2af,
  fields: [
    { name: '📰 News report', value: fit(`**${article.title ?? 'Untitled'}**\n${source}`, 1024), inline: false },
    { name: '🔎 Cross-reference', value: fit(`Matched: ${matched.join(', ') || 'Not provided'}\nConfidence: **${confidence}%**`, 1024), inline: false },
    { name: '🛡️ SOC evidence', value: fit(evidence, 1024), inline: false },
    { name: '🧠 Independent review', value: fit(review.rationale, 1024), inline: false },
    ...(actions.length ? [{ name: '⚡ Suggested next steps', value: fit(actions.join('\n'), 1024), inline: false }] : []),
  ],
  footer: { text: 'Loom · two-model consensus · aggregate SOC evidence only' },
  timestamp: new Date().toISOString(),
};
return { json: { discordEmbed } };
